def is_nested(string):
    stack = []
    has_nested = False

    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']':
            if stack:
                stack.pop()
                if len(stack) > 0:  # If there are already opening brackets in the stack, it's nested
                    has_nested = True

    return has_nested

